using RevenuUsage.Application.Features.ReservesAndObligations;namespace RevenuUsage.Tests;public sealed class ReserveObligationValidatorTests{[Fact]public async Task Empty_reserve_is_rejected(){var r=await new CreateReserveValidator().ValidateAsync(new CreateReserveCommand(DateTime.Today,0,0,0,null,"user"));Assert.False(r.IsValid);}[Fact]public async Task Obligation_requires_currency_client_and_positive_amount(){var r=await new CreateObligationValidator().ValidateAsync(new CreateObligationCommand(DateTime.Today,"",Guid.Empty,0,null,null,null,"user"));Assert.True(r.Errors.Count>=3);}[Fact]public async Task Due_date_cannot_precede_obligation_date(){var date=DateTime.Today;var r=await new CreateObligationValidator().ValidateAsync(new CreateObligationCommand(date,"Client",Guid.NewGuid(),10,date.AddDays(-1),null,null,"user"));Assert.Contains(r.Errors,x=>x.PropertyName=="DueDate");}}
